            "tekst": "Norge er et flerkulturelt samfunn. Innvandring, globalisering og økt mobilitet har gjort at vektere daglig møter mennesker med svært ulik kulturell, etnisk og religiøs bakgrunn. Dette er en berikelse for samfunnet — men det stiller også krav til kulturforståelse og kommunikasjonskompetanse hos alle som jobber i publikumsrettede yrker."
